CREATE OR REPLACE FUNCTION public.record_payment(_booking_id uuid DEFAULT NULL,_tenant_account_id uuid DEFAULT NULL,_amount numeric DEFAULT 0,_method text DEFAULT 'cash',_notes text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE party uuid;con uuid;payload jsonb;receipt uuid;allocation jsonb; BEGIN PERFORM public.finance_assert_writer(); BEGIN payload:=_notes::jsonb;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'تسجيل الدفعة يحتاج تاريخ السداد الفعلي والضريبة؛ استخدم صفحة الإيصالات'; END; IF payload IS NULL OR nullif(payload->>'paid_at','') IS NULL OR payload->>'vat_amount' IS NULL THEN RAISE EXCEPTION 'تاريخ السداد الفعلي والضريبة مطلوبان'; END IF; IF _booking_id IS NOT NULL THEN SELECT party_id INTO party FROM public.bookings WHERE id=_booking_id AND archived_at IS NULL; ELSIF _tenant_account_id IS NOT NULL THEN SELECT party_id INTO party FROM public.tenant_accounts WHERE id=_tenant_account_id AND archived_at IS NULL; END IF; IF party IS NULL THEN RAISE EXCEPTION 'الدفعة تحتاج عميلًا مرتبطًا ومراجَعًا';END IF;receipt:=public.record_receipt(payload||jsonb_build_object('party_id',party,'booking_id',_booking_id,'amount_excl_vat',_amount,'method',_method),payload->>'reason');FOR allocation IN SELECT * FROM jsonb_array_elements(coalesce(payload->'allocations','[]')) LOOP PERFORM public.allocate_receipt(receipt,(allocation->>'installment_id')::uuid,(allocation->>'amount_excl_vat')::numeric,(allocation->>'vat_amount')::numeric,payload->>'reason');END LOOP;RETURN receipt;END $$;
CREATE OR REPLACE FUNCTION public.update_draft_contract(_id uuid,_data jsonb,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.contracts;BEGIN PERFORM public.finance_assert_writer();PERFORM public._assert_reason(_reason);SELECT * INTO c FROM public.contracts WHERE id=_id FOR UPDATE;IF NOT FOUND OR c.status<>'draft' THEN RAISE EXCEPTION 'تعديل بيانات العقد متاح للمسودة فقط';END IF;UPDATE public.contracts SET start_date=coalesce(nullif(_data->>'start_date','')::date,start_date),end_date=coalesce(nullif(_data->>'end_date','')::date,end_date),signed_at=coalesce(nullif(_data->>'signed_at','')::timestamptz,signed_at),payment_plan_id=coalesce(nullif(_data->>'payment_plan_id','')::uuid,payment_plan_id),vat_rate=coalesce(nullif(_data->>'vat_rate','')::numeric,vat_rate),documents=coalesce(_data->'documents',documents),updated_at=now(),reason=_reason WHERE id=c.id;PERFORM public.finance_audit('DRAFT_CONTRACT_UPDATED','contracts',c.id,to_jsonb(c),(SELECT to_jsonb(x) FROM public.contracts x WHERE id=c.id),_reason);END $$;
REVOKE ALL ON FUNCTION public.update_draft_contract(uuid,jsonb,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.update_draft_contract(uuid,jsonb,text) TO authenticated;
-- Restore transaction-local capability cleanup; this deletes only internal authorization tokens, never business records.
DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.set_unit_status(uuid,public.unit_leasing_status,text,text,uuid)'::regprocedure) INTO d;d:=replace(d,'INSERT INTO public.unit_status_history(unit_id,from_status,to_status,actor,actor_role,reason,ref_type,ref_id)','DELETE FROM public.unit_status_write_capabilities WHERE transaction_id=txid_current() AND unit_status_write_capabilities.unit_id=u.id; INSERT INTO public.unit_status_history(unit_id,from_status,to_status,actor,actor_role,reason,ref_type,ref_id)');EXECUTE d;END $$;
SELECT pg_get_functiondef('public.record_payment(uuid,uuid,numeric,text,text)'::regprocedure) LIKE '%record_receipt%' AS receipt_writer;